import sys

class Graph:
    def __init__(self, n):
        self.adj = [[] for _ in range(n)]
        self.weights = [sys.maxsize] * n

    def add_edge(self, u, v, weight):
        self.adj[u].append((v, weight))
        self.adj[v].append((u, weight))

    def dijkstra(self, src, dest):
        visited = [False] * len(self.adj)
        dist = [sys.maxsize] * len(self.adj)
        dist[src] = 0
        pq = [(0, src)]

        while pq:
            current_weight, current_node = heapq.heappop(pq)

            if visited[current_node]:
                continue

            visited[current_node] = True

            for neighbor, weight in self.adj[current_node]:
                if not visited[neighbor] and dist[neighbor] > current_weight + weight:
                    dist[neighbor] = current_weight + weight
                    heapq.heappush(pq, (current_weight + weight, neighbor))

        if dist[dest] == sys.maxsize:
            return -1

        return dist[dest]

