import sys
from collections import deque

def reachability(graph, start, end):
    queue = deque()
    visited = set()
    queue.append(start)
    while queue:
        current = queue.popleft()
        if current == end:
            return True
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append(neighbor)
    return False

def destroy_planets(graph, start, end):
    stack = [start]
    visited = set()
    levels = {}
    levels[start] = 0
    min_level = sys.maxsize
    while stack:
        current = stack.pop()
        if current == end:
            return True, min_level
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                levels[neighbor] = levels[current] + 1
                min_level = min(min_level, levels[neighbor])
                if levels[neighbor] > min_level:
                    continue
                stack.append(neighbor)
    return False, min_level

def process_queries(n, queries):
    graph = [set() for _ in range(2**n)]
    for l, r in queries:
        l, r = l, r
        for i in range(n):
            if (1 << i) <= r:
                row = []
                for j in range(n):
                    if (1 << j) <= r:
                        row.append(1 if (1 << j) & (1 << i) else 0)
                    else:
                        row.append(0)
                graph[l - 1].add((r - 1) << 4 + i)
                if i != n - 1:
                    row = unpack_binary(row)
                    for j in range(row):
                        if j == n:
