import sys

def find_minimum_deck(n, a):
    a.sort()
    result = []
    used = [False] * 20
    max_value = 0
    for ai in a:
        if ai > max_value:
            max_value = ai
            result = []
        while max_value - ai > 0:
            max_value -= 1
            for i in range(20 - 1, -1, -1):
                if (1 << i) <= max_value:
                    result.append(1 << i)
                    used[i] = True
                    max_value -= (1 << i)
    index = n // 2
    for i in range(20 - 1, -1, -1):
        count = 0
        for j in range(index):
            if used[i]:
                count += 1
        if count % 2 == 0:
            index *= 2
        else:
            index *= 3
    i = 20 - 1
    deck = []
    for _ in range(index):
        while i > -1:
            if used[i]:
                deck.append(0)
                i -= 1
            else:
                deck.append(1 << i)
                i -= 1
    return index, sorted(deck)

