from functools import lru_cache
from itertools import accumulate

MOD = 998244353

def merge_sequence(x, y, sequence):
    i = 0
    merged = 0
    for c in accumulate(sequence):
        if c == 0:
            if x[i] == '0':
                merged += 1
                x = x[1:] + x[:1]
                i += 1
        elif c == 1:
            if y[i] == '0':
                merged += 1
                y = y[1:] + y[:1]
                i += 1
        if i == len(x) or i == len(y):
            break
    return merged

@lru_cache(maxsize=None)
def count_sequences(x, y, l1, r1, l2, r2):
    if l1 >= r1 or l2 >= r2:
        return 0
    elif r1 - l1 == 0 and r2 - l2 == 0:
        return 1
    elif r1 - l1 == 1:
        if x[l1] == '0' and y[l2] == '0':
            return count_sequences(x, y, l1, r1, l2, r2 + 1) + count_sequences(x, y, l1, r1, l2 + 1, r2)
        else:
            return count_sequences(x, y, l1, r1, l2, r2)
    elif r2 - l2 == 1:
        if y[l2] == '0' and x[l1] == '0':
            return count_sequences(x, y, l1, r1 + 1, l2, r2) + count_sequences(x, y, l1, r1, l2 + 1, r2)
        else:
            return count_sequences(x, y, l1, r1, l2, r2)
    else:
        for end1 in range(l1, r1 + 1):
            for end2 in range(l2, r2 + 1):
                merged = merge_sequence(x[:end1-l1], y[:end2-l2], end1-end2)
                result = 1 + count_sequences(x, y, l1, end1-1, l2, end2-1) * merged
                yield result % MOD

