class GeographicMap:
    def __init__(self, n):
        self.n = n
        self.bit_map = [[1 << i for i in range(n)] for _ in range(n)]

    def destroy_planets(self, l, r, bit_map):
        for i in range(l - 1, r):
            left_bit_map = bit_map[i - 1]
            right_bit_map = bit_map[i]
            for j in range(n - 1):
                new_bit_map = [left_bit_map[i] | (1 << j) if (x == j) else right_bit_map[i] | (1 << j) for i, x in enumerate(range(self.n))]
                self.bit_map.remove(new_bit_map)
                self.bit_map.append(new_bit_map)

    def is_fixed(self, bits):
        for i, bit in enumerate(bits):
            if bit != (1 << i):
                return False
        return True

    def is_query_possible(self, a, b):
        if self.is_fixed(self.bit_map[a - 1]):
            return False
        for i in range(a - 1):
            if self.is_fixed(self.bit_map[i]):
                return False
        return self.is_fixed([self.bit_map[b - 1]])        

def process_queries(n, m, queries, mapObj):
    results = []

    for query in queries:
        seg_split = query.split()
        if seg_split[0] == "block":
            s, e = map(int, seg_split[2:])
            mapObj.destroy_planets(s, e, mapObj.bit_map)
            mapObj.bit_map.append([((1 << i) & ((1 << (n - 1)) - 1)) for i in range(3 * n)])

        elif seg_split[0] == "ask":
            results.append("1" if mapObj.is_query_possible(int(seg_split[1]), int(seg_split[2])) else "0")

    return results

