from collections import deque

def find_solution(button_count, possible_passwords):
    # Initialize progress map and delimiters
    progress = [[False for _ in range(button_count)] for _ in range(button_count + 1)]
    delimiters = ['0']
    for j in range(1, button_count + 1):
        one_positions = [idx for idx, pwd in enumerate(possible_passwords) if pwd[-j] == '1']
        progress[1][j] = one_positions
        delimiters.append(str(j-1))

    # Construct the shortest solution
    queue = deque([progress.copy()])
    solution = []
    for x in queue:
        x = [i for i in x]
        index = x.pop(0)
        while len(x) > 0:
            new_x = []
            startIndex = 1
            for x in progress[index + 1]:
                possible_insertions = 0
                for j in range(button_count + startIndex, len(x)):
                    if x[j] != '0':
                        if ((delimiters[j] not in x[startIndex - startIndex:(startIndex + len(x[startIndex:])-j)]) and (x[0:j][::-1] != x[j:])):
                            possible_insertions += 1
                if possible_insertions > 0:
                    startIndex += possible_insertions
                    for i in range(possible_insertions):
                        new_x.append(x[startIndex + i:]}
            x = new_x
            x.insert(0, progress[index + 1])
    return solution

