def is_bad_coloring(intervals):
    adjacency_matrix = [[0] * len(intervals) for _ in range(len(intervals))]

    for i, (si1, ei1) in enumerate(intervals):
        for j, (si2, ei2) in enumerate(intervals):
            if si2 >= si1 and ei2 <= ei1:
                adjacency_matrix[i][j] = 1

    for i, row in enumerate(adjacency_matrix):
        for j, row_col in enumerate(takewhile(lambda x: x != 1, row)):
            if not row_col and i != j:
                return 2  # fiffs in fourth case

    return 1

