from collections import deque

def find_min_presses(d, passwords):
    n = len(passwords)
    visited = set()
    answer = [0 for _ in range(n)]
    max_depth = 0

    for i in range(n):
        depth = 0
        queue = deque([i])
        while queue:
            size = len(queue)
            for _ in range(size):
                node = queue.popleft()
                if node not in visited:
                    if not visited:
                        max_depth = depth
                    visited.add(node)
                    if passwords[node]:
                        for j in range(d):
                            if passwords[node][j]:
                                answer[node] |= 1 << j
                            if j < d - 1:
                                queue.append(node | (1 << j))
                    else:
                        for j in range(d):
                            if not passwords[node][j]:
                                queue.append(node)
            depth += 1

    solution = []
    for i in range(n):
        for j in range(1 << d):
            if j & answer[i]:
                solution.append(j)
                solution.append('R')
                break
        else:
            solution.append('0')

    return len(solution), solution

d, n = map(int, input().split())
passwords = [list(map(int, input().strip())) for _ in range(n)]
