def is_nice_coloring(intervals):
    interval_dict = defaultdict(list)
    for s, e in intervals:
        interval_dict[(s, e)].append(1)
        interval_dict[(e - 1, s - 1)].append(0)

    disjoint_sets = [i for i in range(2**len(intervals))]

    for i in range(len(intervals)):
        for j in range(len(intervals)):
            if i == j:
