    for state in g:
        for threshold_i in range(1, 1 + threshold):
            g[state].remove({'tolerance': threshold_i})
            g2 = g[state].copy()
            g2_sorted = sorted([(val, id) for val, id in g2.items()])
            indices = list(range(len(g2)))
