            for i in range(indices1 + 1):
                indices3 = [id for id in indices[i:]]
                delta = state.update_threshold_indices(indices, indices3, len(indices3))
            for id in indices3:
                state.replace_id_indices(id, indices1 + len(indices3) - 1, delta)

