        possible_password = bin(int(current_password, 2))[2:].zfill(d)
        result.reverse()
        for i in range(passwords_index[result.pop()], len(possible_passwords)):
            if possible_passwords[i] != possible_password:
                possible_passwords[i] = possible_passwords[i][:i] + possible_passwords[i][i+1:]+current_password[:passwords_index[result.pop()]:2][::-1] + current_password[passwords_index[result.pop()]::2]
                possible_passwords = list(set(possible_passwords))
                break
        result.reverse()
        result.add(possible_passwords_index[possible_password])

def passwords_index(passwords):
    index = 0
    for bits in passwords:
        for i in range(len(bits)):
            if bits[i] == '1':
                index += 2 ** (len(bits)-i-1)
    return index

