def compute_sum_of_gcds(n, m):
    mod = 10**9 + 7
    is_prime = [True for _ in range(n+1)]
    is_prime[0] = False
    is_prime[1] = False
    for i in range(2, int(n**0.5)+1):
        if is_prime[i]:
            # Update multiples of the prime number
            for j in range(i*i, n+1, i):
                is_prime[j] = False
    lpms = [is_prime[j]: enumerate(is_prime, i) for i, j in enumerate(is_prime)]

    seg = [lpms[i] for i in range(n+1)]
    newsseg = []
    for i in range(n+1):
        if seg[i][0] + seg[i][1][i-1][-1]:
            newsseg.append(segs)

    return sum(sum(segs) for segs in newsseg)


def f(n, k):
